    window.__CHARS_FULL = chars;

    /* ══════════════ ẢNH NHÂN VẬT + KHUNG LỚN · thêm 11/10/2026 ══════════════ */
    const CS_DIR = 'chars/';   // thư mục ảnh: chars/pic001.jpg … chars/pic120.jpg (đúng số thứ tự 01/120)
    /* 08/11/2026 — 10 nhân vật mới dùng ảnh pic121→pic130 (đuôi .png) */
    const PIC_FIX = {
      "Huyền Quy":"pic121", "Charlotte Ha-eun Richter":"pic122", "Séraphine Valcourt":"pic123",
      "Lâm Tinh Vũ remake":"pic124", "Lục Dư An remake":"pic125", "Thẩm Ngược Vũ remake":"pic126",
      "Lục Ý Hiên remake":"pic127", "Xám Tro":"pic128", "Đoàn Thị Triều":"pic129", "Tạ Ngưng Quang":"pic130"
    };
    function picBase(i){ return (chars[i] && PIC_FIX[chars[i].name]) || ('pic'+String(i+1).padStart(3,'0')); }
    function picExt(i){ return (chars[i] && PIC_FIX[chars[i].name]) ? ['.png','.jpg'] : ['.jpg','.png']; }
    /* ảnh bìa: chars/pic001.jpg → pic001.jpg (gốc repo) → chars/pic001_1.jpg → pic001_1.jpg */
    function coverCands(i){ const b=picBase(i), out=[]; picExt(i).forEach(function(e){ out.push(CS_DIR+b+e, b+e, CS_DIR+b+'_1'+e, b+'_1'+e); }); return out; }
    chars.forEach((c,i)=>{ c.__i=i; const cd=coverCands(i); c.__img=cd[0]; c.__cands=cd.join(','); });

    /* đổi sang đường dẫn kế tiếp khi ảnh lỗi */
    window.__imgStep=function(el){
      const cands=(el.getAttribute('data-c')||'').split(',').filter(Boolean);
      let k=parseInt(el.getAttribute('data-k')||'1',10); if(isNaN(k)) k=1;
      if(k<cands.length){ el.setAttribute('data-k',String(k+1)); el.setAttribute('src',cands[k]); return true; }
      el.remove(); return false;
    };
    function __imgAlt(el){ return window.__imgStep(el); }

